parameters.jsonBody:
={{ JSON.stringify({
  model: "claude-sonnet-4-5",
  max_tokens: 8192,
  system: "Du bist ein Social-Media-Experte. Erstelle aus dem folgenden Thema genau 10 Posts: 3 für LinkedIn, 3 für Instagram, 2 für X, 2 für Facebook. Jeder Post ist auf die Plattform optimiert.\n\nPlattform-Anforderungen:\n- LinkedIn: Professionell, Storytelling, 1.000–1.500 Zeichen, 3–5 Hashtags, Hook im ersten Satz\n- Instagram: Kurz, emotional, Call-to-Action, 10–15 Hashtags, Emoji-freundlich, Absätze mit Leerzeilen\n- X (Twitter): Knapp, Hook in den ersten Worten, max 280 Zeichen, 2–3 Hashtags, kontroverse Meinungen funktionieren\n- Facebook: Mittellang, Fragen stellen, Community-orientiert, persönlicher Ton\n\nRufe das Tool output_posts mit genau 10 Posts im posts-Array auf.",
  tools: [
    {
      name: "output_posts",
      description: "Gibt die generierten Social-Media-Posts strukturiert zurück",
      strict: true,
      input_schema: {
        type: "object",
        properties: {
          posts: {
            type: "array",
            items: {
              type: "object",
              properties: {
                platform: { type: "string", enum: ["linkedin", "instagram", "x", "facebook"] },
                text: { type: "string" },
                hashtags: { type: "array", items: { type: "string" } },
                suggested_image: { type: "string" },
                best_time: { type: "string" }
              },
              required: ["platform", "text", "hashtags", "suggested_image", "best_time"],
              additionalProperties: false
            }
          }
        },
        required: ["posts"],
        additionalProperties: false
      }
    }
  ],
  tool_choice: { type: "tool", name: "output_posts" },
  messages: [
    {
      role: "user",
      content: "Thema: " + $json.body.thema + "\nKontext: " + ($json.body.kontext || "-") + "\nMarkenstimme: " + ($json.body.markenstimme || "-") + "\nZielgruppe: " + ($json.body.zielgruppe || "-")
    }
  ]
}) }}

parameters.jsCode:
const response = $input.first().json;
const toolUse = response.content.find((c) => c.type === 'tool_use');
const rawPosts = toolUse.input.posts;
const posts = typeof rawPosts === 'string' ? JSON.parse(rawPosts) : rawPosts;

const platformMap = {
  linkedin: 'LinkedIn',
  instagram: 'Instagram',
  x: 'X',
  facebook: 'Facebook'
};

return posts.map((post) => ({
  json: {
    platform: platformMap[post.platform.toLowerCase()] || post.platform,
    text: post.text,
    hashtags: Array.isArray(post.hashtags) ? post.hashtags.join(' ') : post.hashtags,
    suggested_image: post.suggested_image,
    best_time: post.best_time
  }
}));
